{
  "name": "@khaosoigai/oc-context-grid",
  "version": "0.3.2",
  "description": "Claude Code-style context usage pixel-grid for the OpenCode TUI",
  "keywords": [
    "opencode",
    "opentui",
    "tui",
    "context-window",
    "solid-js",
    "plugin"
  ],
  "type": "module",
  "exports": {
    "./tui": "./dist/index.js"
  },
  "engines": {
    "opencode": "^2.0.0"
  },
  "files": [
    "dist"
  ],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/khaosoi/oc-context-grid-plugin.git"
  },
  "scripts": {
    "build": "bun run scripts/build.ts",
    "prepack": "bun run build",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "license": "MIT",
  "devDependencies": {
    "@opencode/client": "2.0.28",
    "@opencode/plugin": "2.0.28",
    "@opencode/theme": "2.0.28",
    "@opentui/core": "0.6.4",
    "@opentui/solid": "0.6.4",
    "bun-types": "^1.4.0",
    "solid-js": "1.9.17",
    "typescript": "^7.0.2"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.0",
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": "^1.9.10"
  }
}
